<template>
 <view class="distribution">
  <view v-if="error" class="card">{{error}}<button class="ui-button" @click="load">重试</button></view>
  <template v-if="data">
   <view class="summary"><text class="hint light">可用佣金</text><text class="amount">¥{{money(Math.max(0,data.available))}}</text><view class="row"><text>{{data.settings.tiers[data.profile[0]?.tier||0]}}</text><button class="ui-button withdraw" :disabled="data.frozen||data.available<=0" @click="go('withdraw')">提现</button></view><text v-if="data.frozen" class="hint light">暂不可提现：{{data.profile[0]?.reason}}</text><text v-if="data.available<0" class="hint light">退款待扣回 ¥{{money(-data.available)}}</text></view>
   <view class="card row" @click="go('sales-orders')"><text class="heading">我卖出的订单</text><text class="hint">查看客户成交与佣金 ›</text></view><view class="tools"><button class="ui-button" @click="go('promote')">选品推广</button><button class="ui-button" @click="go('promo-materials')">素材与文案</button><button class="ui-button" @click="go('withdrawals')">提现记录</button></view>
   <view class="tabs"><view v-for="t in tabs" :key="t.key" :class="{active:tab===t.key}" @click="tab=t.key">{{t.label}}</view></view>
   <view v-if="tab==='overview'" class="card"><view class="row"><text>近365天订单净业绩</text><text>¥{{money(data.performance)}}</text></view><view class="row"><text>团队人数</text><text>{{data.team.length}} 人</text></view><text v-if="data.settings.autoTier" class="hint">{{(data.profile[0]?.tier||0)>=2?'已达最高等级':'下一等级门槛 ¥'+money((data.profile[0]?.tier||0)===0?data.settings.silver:data.settings.gold)}} · 每天更新</text><text v-else class="hint">当前等级由商家设置</text><view class="row" @click="sourceOpen=!sourceOpen"><text>推荐来源</text><text class="hint">{{data.referrer?'已绑定':'未绑定'}} {{sourceOpen?'⌃':'›'}}</text></view><template v-if="sourceOpen"><text v-if="data.referrer" class="hint">推荐编号 {{data.referrer}}<text v-if="data.referrerExpiresAt"> · 有效至 {{formatDate(data.referrerExpiresAt)}}</text></text><template v-else><input v-model="referrer" type="number" placeholder="填写邀请人的编号"/><text class="hint">确认后不能自行更换，请核对邀请人编号。</text><button class="ui-button" :disabled="busy||!referrer" @click="bind">确认推荐来源</button></template></template></view>
   <template v-if="tab==='team'"><view class="card"><input v-model="search" placeholder="搜索团队成员"/><view class="filters"><text v-for="n in [0,1,2]" :key="n" :class="{active:depth===n}" @click="depth=n">{{n===0?'全部':n+'级'}}</text></view><view v-for="m in visibleTeam" :key="m.id" class="team-member"><view class="row"><view><text>{{m.nickname}}</text><text class="hint">{{m.depth===1?'一级成员':data.settings.secondEnabled?'二级成员':'二级成员（不产生佣金）'}}</text></view><view><text>{{data.settings.tiers[m.tier]}}</text><text class="edit-note" @click="editMember=m.id;memberNote=m.note||''">{{m.note?'编辑备注':'添加备注'}}</text></view></view><text v-if="m.note" class="hint">{{m.note}}</text></view><text v-if="!visibleTeam.length" class="empty">{{data.team.length?'没有匹配的团队成员':'还没有团队成员，可从工作台邀请伙伴'}}</text><button class="ui-button" @click="go('distribution')">邀请伙伴</button></view></template>
   <template v-if="tab==='rewards'"><view v-for="r in data.rewards" :key="r.id" class="card"><view class="row"><text class="heading">{{r.name}} {{r.spec}} × {{r.quantity||1}}</text><text class="reward">佣金 ¥{{money(r.amount)}}</text></view><text class="hint">{{rewardSource(r)}} · {{orderStatus(r.order_status)}}</text><view class="row"><text>{{rewardPaid(r).label}}</text><text>¥{{money(rewardPaid(r).amount)}}</text></view><text v-if="r.buyer_nickname" class="hint">客户：{{r.buyer_nickname}}</text><text class="hint">订单 {{r.order_no}}</text><view class="row"><text>可用佣金</text><text>¥{{money(r.available_amount)}}</text></view><text v-if="r.reason" class="hint">{{r.reason}}</text><text v-if="r.ready_at" class="hint">下批预计结算 {{formatDate(r.ready_at)}}</text></view><view v-if="!data.rewards.length" class="card empty">暂无商品佣金</view></template>
   <template v-if="tab==='ledger'"><view v-for="r in data.ledger" :key="r.id" class="card"><text>{{r.note}}</text><view class="row"><text>总额变动</text><text>¥{{money(r.delta)}}</text></view><view class="row"><text>可用变动</text><text>¥{{money(r.available_delta)}}</text></view><text class="hint">{{formatDate(r.created_at)}}</text></view><view v-if="!data.ledger.length" class="card empty">暂无佣金变动</view></template>
   <view v-if="editMember" class="note-overlay" @click="editMember=0"><view class="note-dialog" @click.stop><text class="heading">成员备注</text><textarea v-model="memberNote" maxlength="200" placeholder="记录联系进度，仅自己可见"/><view class="tools"><button class="ui-button" @click="editMember=0">取消</button><button class="ui-button" :disabled="busy" @click="saveNote">保存备注</button></view></view></view>
  </template>
 </view>
</template>
<script>
import {request,money,go,notify} from '../services/shop'
import {formatDate} from '../services/display'
import {rewardSource,rewardPaid} from '../services/distribution-rewards'
export default {props:{refreshTick:{default:0}},watch:{refreshTick(){if(!this.editMember)this.load()}},data(){return{editMember:0,memberNote:'',data:null,error:'',referrer:'',busy:false,tab:'overview',sourceOpen:false,search:'',depth:0,tabs:[{key:'overview',label:'概览'},{key:'team',label:'我的团队'},{key:'rewards',label:'商品佣金'},{key:'ledger',label:'资金变动'}]}},computed:{visibleTeam(){return (this.data?.team||[]).filter(m=>(!this.depth||Number(m.depth)===this.depth)&&(!this.search||String((m.nickname||'')+' '+(m.note||'')).includes(this.search.trim())))}},mounted(){this.load()},methods:{money,go,formatDate,rewardSource,rewardPaid,orderStatus(status){return ({pending:'待付款',paid:'已付款',shipping:'配送中',shipped:'已发货',completed:'已完成',cancelled:'已取消',refunded:'已退款',unknown:'待核实'})[status]||'处理中'},async saveNote(){if(this.busy)return;this.busy=true;try{await request('/distribution-team/'+this.editMember+'/note','POST',{note:this.memberNote});this.editMember=0;await this.load()}catch(e){notify(e)}finally{this.busy=false}},async load(){try{this.data=await request('/distribution-detail');this.error=''}catch(e){this.error=e.message}},async bind(){if(this.busy)return;this.busy=true;try{const r=await request('/referral','POST',{referrer:Number(this.referrer)});if(r?.state==='ignored')uni.showToast({title:'推荐人编号无效：不能填自己或自己推荐的人',icon:'none'});else if(r?.state==='kept')uni.showToast({title:'你已有推荐人，不能更换',icon:'none'});await this.load()}catch(e){notify(e)}finally{this.busy=false}}}}
</script>
<style scoped>
@import '../styles/component-base.css';

.team-member{border-bottom:1px solid var(--shop-border, #d5e6ee);padding-bottom:12px}.edit-note{display:block;color:var(--shop-ink, #28546c);font-size:12px;margin-top:4px;text-align:right}.note-overlay{position:fixed;inset:0;background:#0006;z-index:80;display:flex;align-items:flex-end}.note-dialog{background:var(--shop-surface, #fdfeff);width:100%;padding:24px 20px calc(24px + env(safe-area-inset-bottom));border-radius:16px 16px 0 0;box-sizing:border-box}.note-dialog textarea{width:100%;height:120px;background:var(--shop-background, #f3f8fb);padding:12px;box-sizing:border-box;margin:16px 0}

.distribution{padding:12px;font-size:14px}.summary{background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c);padding:22px;border-radius:14px}.amount{display:block;font-size:34px;margin:10px 0}.card{background:var(--shop-surface, #fdfeff);padding:16px;border:1px solid var(--shop-border, #d5e6ee);border-radius:10px;margin-bottom:12px;line-height:1.7}.heading{font-weight:600;font-size:15px}.hint{display:block;font-size:12px;color:var(--shop-muted, #59727f);overflow-wrap:anywhere}.light{color:var(--shop-ink, #28546c)}.row{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:10px 0}.card.row{padding:14px 16px}.row>view{min-width:0}.row>text{overflow-wrap:anywhere}.reward{color:#b87650;white-space:nowrap}input{background:var(--shop-background, #f3f8fb);height:44px;line-height:44px;padding:0 12px;box-sizing:border-box;width:100%;font-size:14px;border-radius:6px;margin:8px 0}button{font-size:13px;background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c);margin-top:12px;line-height:38px}.withdraw{margin:0;background:var(--shop-soft, #eaf5fb);color:var(--shop-ink, #28546c);padding:0 18px}.tools{display:flex;gap:8px;margin-bottom:14px}.tools button{flex:1;background:var(--shop-surface, #fdfeff);color:var(--shop-ink, #28546c);border:1px solid var(--shop-border, #d5e6ee);font-size:12px;padding:0 5px}.tabs,.filters{display:flex;gap:8px;margin:14px 0}.tabs>view{flex:1;text-align:center;font-size:13px;padding:9px 0}.tabs .active{color:var(--shop-ink, #28546c);border-bottom:2px solid var(--shop-control, #417c9a);font-weight:600}.filters>text{padding:4px 14px;background:var(--shop-background, #f3f8fb);border-radius:16px;font-size:12px}.filters .active{background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c)}.empty{display:block;text-align:center;color:var(--shop-muted, #59727f);padding:30px 12px}
</style>
